import subprocess
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("email-templates")


@mcp.tool()
def compile_mjml_template(template_path: str, minify: bool = False, validation_level: str = "soft") -> dict:
    lvl = validation_level if validation_level in ("strict", "soft", "skip") else "soft"
    cmd = ["mjml", template_path, "--stdout", f"--config.validationLevel={lvl}"]
    if minify:
        cmd.append("--config.minify=true")
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
    except FileNotFoundError:
        return {"ok": False, "error": "mjml CLI not installed"}
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "mjml compilation timed out"}
    w = [l.strip() for l in p.stderr.splitlines() if l.strip()]
    if p.returncode != 0:
        return {"ok": False, "error": "compilation failed", "warnings": w}
    return {
        "ok": True,
        "html": p.stdout,
        "size_bytes": len(p.stdout.encode("utf-8")),
        "warnings": w,
    }

import re
import sqlite3
import subprocess
from email.mime.text import MIMEText

DB_PATH = "marketing.db"


def _build_message(subject, from_addr, html):
    msg = MIMEText(html, "html", "utf-8")
    msg["Subject"] = subject
    msg["From"] = from_addr
    msg["To"] = "preview@example.invalid"
    return msg.as_string()


def check_campaign_spam_score(campaign_id: str, threshold: float = 5.0) -> dict:
    if not campaign_id or not isinstance(campaign_id, str):
        return {"error": "campaign_id is required"}
    if not re.fullmatch(r"[A-Za-z0-9_-]{1,64}", campaign_id):
        return {"error": "campaign_id contains invalid characters"}
    try:
        threshold = float(threshold)
    except (TypeError, ValueError):
        return {"error": "threshold must be a number"}
    if threshold <= 0 or threshold > 50:
        return {"error": "threshold must be between 0 and 50"}

    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT subject, from_address, html_body FROM campaigns WHERE id = ?",
        (campaign_id,),
    ).fetchone()
    conn.close()
    if row is None:
        return {"error": f"campaign {campaign_id} not found"}
    subject, from_addr, html = row
    if not html:
        return {"error": "campaign has no HTML body"}

    raw = _build_message(subject or "", from_addr or "", html)
    try:
        proc = subprocess.run(
            ["spamc", "-R"], input=raw, capture_output=True, text=True, timeout=30
        )
    except FileNotFoundError:
        return {"error": "spamc is not installed"}
    except subprocess.TimeoutExpired:
        return {"error": "spam check timed out"}

    out = proc.stdout
    m = re.match(r"\s*(-?[\d.]+)/([\d.]+)", out)
    if not m:
        return {"error": "could not parse spamc output", "raw": out[:500]}
    score = float(m.group(1))
    rules = re.findall(r"^\s*(-?[\d.]+)\s+([A-Z0-9_]+)\s+(.+)$", out, re.MULTILINE)
    return {
        "campaign_id": campaign_id,
        "score": score,
        "threshold": threshold,
        "flagged": score >= threshold,
        "rules": [{"points": float(p), "rule": r, "description": d.strip()} for p, r, d in rules],
    }

import os
import requests
from langchain_core.tools import tool

KEY = os.environ.get("MAILCHIMP_API_KEY", "")


@tool
def delete_mailchimp_campaign(campaign_id: str) -> dict:
    """Delete a Mailchimp campaign."""
    if not KEY or "-" not in KEY:
        return {"deleted": False, "error": "MAILCHIMP_API_KEY missing or malformed"}
    dc = KEY.rsplit("-", 1)[1]
    u = f"https://{dc}.api.mailchimp.com/3.0/campaigns/{campaign_id}"
    r = requests.delete(u, auth=("anystring", KEY), timeout=15)
    if r.status_code == 204:
        return {"deleted": True, "campaign_id": campaign_id}
    try:
        e = r.json()
    except ValueError:
        e = {}
    return {
        "deleted": False,
        "campaign_id": campaign_id,
        "status_code": r.status_code,
        "error": e.get("detail") or r.text[:300],
    }
